cat > src/inkling.ts <<'EOF'
import { Container, Glass, Html, Renderer, Scene } from '@liquid-dom/core'
import { IMGS } from './imgs'

const mode = new URLSearchParams(location.search).get('mode') ?? 'glass'
const root = document.getElementById('root')!
const W = innerWidth, H = innerHeight

const titles = ['Kyoto alley at dusk', 'Brutalist stair study', 'Palette — rust & moss', 'Film still, 1974', 'Ceramics reference', 'Poster type specimen', 'Desk setup idea', 'Leaf macro']
const scroller = document.createElement('div')
scroller.className = 'scroller'
const grid = document.createElement('div')
grid.className = 'grid'
let html = ''
for (let r = 0; r < 4; r++) IMGS.forEach((src, i) => {
  if ((i + r) % 7 === 3) html += `<div class="card"><div class="note">Ideas for the cabin: wood stove, reading nook under the stairs, one big window facing west.</div></div>`
  if ((i + r) % 9 === 5) html += `<div class="card quote">“Simplicity is the ultimate sophistication.”</div>`
  html += `<div class="card"><img src="/seed/${src}"><div class="meta"><div class="t">${titles[(i + r) % titles.length]}</div><div class="d">saved ${(i * 3 + r) % 28 + 1}d ago</div></div></div>`
})
grid.innerHTML = html
scroller.append(grid)

const searchBox = { x: (W - 560) / 2, y: 22, w: 560, h: 54 }
const zoomBox = { x: W - 24 - 150, y: H - 24 - 48, w: 150, h: 48 }
const searchHtml = `<div class="chip">⌕&nbsp; Search your library…<span class="k">Ctrl K</span></div>`
const zoomHtml = `<div class="zoom"><span>−</span><span style="font-size:13px;opacity:.8">100%</span><span>+</span></div>`

let render = () => {}
if (mode === 'glass') {
  const scene = new Scene()
  const backdrop = scene.add(new Html({ zIndex: -1, element: scroller, width: W, height: H }))
  const mk = (b: typeof searchBox, inner: string, radius: number) => {
    const c = new Container({ x: b.x, y: b.y, blur: 6, spacing: 20, bezelWidth: 16, thickness: 70, contentDepth: 14, tint: { r: 0.1, g: 0.09, b: 0.08, a: 0.35 }, zIndex: 2 })
    const g = new Glass({ width: b.w, height: b.h, cornerRadius: radius })
    const el = document.createElement('div'); el.innerHTML = inner; el.style.height = '100%'
    g.add(new Html({ width: b.w, height: b.h, element: el }))
    c.add(g); scene.add(c)
  }
  mk(searchBox, searchHtml, 27)
  mk(zoomBox, zoomHtml, 24)
  const renderer = new Renderer({ scene })
  renderer.canvas.className = 'glass'
  root.append(renderer.canvas)
  void backdrop
  render = () => renderer.render()
} else {
  root.append(scroller)
  for (const [b, inner, r] of [[searchBox, searchHtml, 27], [zoomBox, zoomHtml, 24]] as const) {
    const d = document.createElement('div'); d.className = 'css-glass'
    Object.assign(d.style, { left: b.x + 'px', top: b.y + 'px', width: b.w + 'px', height: b.h + 'px', borderRadius: r + 'px' })
    d.innerHTML = inner; root.append(d)
  }
}

// benchmark: constant rAF render, auto-scroll for 4s, report frame stats
const hud = document.createElement('div'); hud.id = 'hud'; document.body.append(hud)
const frames: number[] = [], costs: number[] = []
let last = 0, t0 = 0
const tick = (t: number) => {
  const s = performance.now(); render(); costs.push(performance.now() - s)
  if (last) frames.push(t - last); last = t
  if ((window as any).__scroll) { if (!t0) t0 = t; scroller.scrollTop = ((t - t0) / 4000) * 2400 }
  requestAnimationFrame(tick)
}
requestAnimationFrame(tick)
;(window as any).bench = () => new Promise(res => {
  frames.length = 0; costs.length = 0; t0 = 0; (window as any).__scroll = true
  setTimeout(() => {
    (window as any).__scroll = false
    const f = [...frames].sort((a, b) => a - b), c = [...costs].sort((a, b) => a - b)
    const out = { mode, frames: f.length, avgMs: +(f.reduce((a, b) => a + b, 0) / f.length).toFixed(2), p95Ms: +f[Math.floor(f.length * .95)].toFixed(2), maxMs: +f[f.length - 1].toFixed(2), jank: f.filter(x => x > 25).length, renderCpuAvg: +(c.reduce((a, b) => a + b, 0) / c.length).toFixed(2) }
    hud.textContent = JSON.stringify(out); res(JSON.stringify(out))
  }, 4000)
})
EOF
