// Zoom is screen pixels per image pixel. It runs continuously from the fitted
// size up to MAX_ZOOM (3200%).
export const MAX_ZOOM = 32;
// From this zoom on, an image pixel is large enough to read as a square, so the
// image renders pixelated and the grid appears.
export const PIXEL_ZOOM = 8;
// One button press scales by this much, so each step feels the same size at 20%
// as at 2000%.
export const BUTTON_ZOOM_FACTOR = 1.25;
// Ctrl+wheel: a typical 100px notch scales by about 1.22.
const WHEEL_ZOOM_RATE = 0.002;

export type Size = { width: number; height: number };
export type Offset = { x: number; y: number };

export function clampZoom(zoom: number, fit: number): number {
  return Math.min(Math.max(fit, MAX_ZOOM), Math.max(fit, zoom));
}

export function wheelZoomFactor(deltaY: number): number {
  return Math.exp(-deltaY * WHEEL_ZOOM_RATE);
}

// Pan moves the image only as far as it overhangs the frame, so the frame stays
// covered. An image smaller than the frame in one axis stays centred on it.
export function clampPan(pan: Offset, shown: Size, frame: Size): Offset {
  const maxX = Math.max(0, (shown.width - frame.width) / 2);
  const maxY = Math.max(0, (shown.height - frame.height) / 2);
  return {
    x: Math.min(maxX, Math.max(-maxX, pan.x)),
    y: Math.min(maxY, Math.max(-maxY, pan.y)),
  };
}

// The pan that keeps the image point under `anchor` (frame-centre coordinates)
// in place while the zoom changes from `from` to `to`.
export function panAround(pan: Offset, anchor: Offset, from: number, to: number): Offset {
  const ratio = to / from;
  return {
    x: anchor.x - (anchor.x - pan.x) * ratio,
    y: anchor.y - (anchor.y - pan.y) * ratio,
  };
}

import { expect, test } from "bun:test";
import { clampPan, clampZoom, MAX_ZOOM, panAround, wheelZoomFactor } from "./imageZoom";

test("zoom stays between the fitted size and the maximum", () => {
  expect(clampZoom(0.05, 0.14)).toBe(0.14);
  expect(clampZoom(100, 0.14)).toBe(MAX_ZOOM);
  expect(clampZoom(0.5, 0.14)).toBe(0.5);
});

test("an image that fits above the maximum never zooms below fit", () => {
  expect(clampZoom(10, 40)).toBe(40);
});

test("zooming around a point keeps that point under the cursor", () => {
  const anchor = { x: 120, y: -40 };
  const pan = { x: 10, y: 5 };
  const next = panAround(pan, anchor, 0.5, 2);
  // The image point under the anchor, in image pixels, is the same before and after.
  expect((anchor.x - pan.x) / 0.5).toBeCloseTo((anchor.x - next.x) / 2);
  expect((anchor.y - pan.y) / 0.5).toBeCloseTo((anchor.y - next.y) / 2);
});

test("zooming around the centre scales the pan", () => {
  expect(panAround({ x: 10, y: -4 }, { x: 0, y: 0 }, 1, 2)).toEqual({ x: 20, y: -8 });
});

test("wheel down zooms out and wheel up zooms in", () => {
  expect(wheelZoomFactor(100)).toBeLessThan(1);
  expect(wheelZoomFactor(-100)).toBeGreaterThan(1);
  expect(wheelZoomFactor(100) * wheelZoomFactor(-100)).toBeCloseTo(1);
});

test("pan stops where the image edge meets the frame", () => {
  const shown = { width: 400, height: 100 };
  const frame = { width: 200, height: 200 };
  expect(clampPan({ x: 500, y: 50 }, shown, frame)).toEqual({ x: 100, y: 0 });
});

