if (!page) throw new Error("no app page: " + JSON.stringify(list.map((t: { url: string }) => t.url)));
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r, { once: true }));
let id = 0;
const pending = new Map<number, (v: any) => void>();
ws.addEventListener("message", (e) => {
  const msg = JSON.parse(String(e.data));
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)!(msg); pending.delete(msg.id); }
});
const send = (method: string, params: object = {}) => new Promise<any>((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
for (let i = 0; i < rest.length; i += 2) {
  const cmd = rest[i], arg = rest[i + 1];
  if (cmd === "eval") {
    const res = await send("Runtime.evaluate", { expression: arg, awaitPromise: true, returnByValue: true });
    console.log(JSON.stringify(res.result?.result?.value ?? res.result?.exceptionDetails ?? res, null, 1));
  } else if (cmd === "shot") {
    const res = await send("Page.captureScreenshot", { format: "png" });
    await Bun.write(arg, Buffer.from(res.result.data, "base64"));
    console.log("shot", arg);
  } else if (cmd === "wait") {
    await Bun.sleep(Number(arg));
  } else if (cmd === "cdp") {
    const [method, params] = arg.split(/ (.*)/s);
    const res = await send(method, params ? JSON.parse(params) : {});
    console.log(JSON.stringify(res.result ?? res.error).slice(0, 2000));
  }
}
ws.close();

