// bun perf.ts <port> <liquid|css>  — reloads the app in that mode, then measures
// frame deltas while wheel-scrolling the grid and while toggling the sidebar,
// and counts library canvas paints while idle.
const [portArg, mode] = process.argv.slice(2);
const list = await (await fetch(`http://127.0.0.1:${portArg}/json/list`)).json();
const page = list.find((t: { url: string; type: string }) => t.type === "page" && t.url.startsWith("app://"));
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r, { once: true }));
let id = 0;
const pending = new Map<number, (v: any) => void>();
ws.addEventListener("message", (e) => {
  const msg = JSON.parse(String(e.data));
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)!(msg); pending.delete(msg.id); }
});
const send = (method: string, params: object = {}) => new Promise<any>((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const evaluate = async (expression: string) => (await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true })).result?.result?.value;

const injected = await send("Page.addScriptToEvaluateOnNewDocument", {
  source: mode === "css" ? "delete HTMLCanvasElement.prototype.layoutSubtree;" : "",
});
await send("Page.reload", {});
await Bun.sleep(3500);
await send("Page.removeScriptToEvaluateOnNewDocument", { identifier: injected.result.identifier });
console.log(mode, "liquid targets:", await evaluate(`document.querySelectorAll("[data-liquid]").length`));

const recorder = `(() => { window.__d = []; window.__rec = true; let last = performance.now();
  const f = (t) => { window.__d.push(t - last); last = t; if (window.__rec) requestAnimationFrame(f); };
  requestAnimationFrame(f); })()`;
const stats = `(() => { window.__rec = false; const d = window.__d.slice(2).sort((a, b) => a - b);
  const q = (p) => d[Math.min(d.length - 1, Math.floor(p * d.length))];
  return { frames: d.length, median: +q(0.5).toFixed(1), p95: +q(0.95).toFixed(1), max: +d[d.length - 1].toFixed(1), over25ms: d.filter((x) => x > 25).length }; })()`;

// Idle: paints on the library canvas with nothing happening.
await evaluate(`(() => { window.__paints = 0; document.querySelector(".library-stage .liquid-glass-canvas")?.addEventListener("paint", () => window.__paints++); })()`);
await Bun.sleep(2000);
console.log("idle paints in 2s:", await evaluate("window.__paints"));

// Wheel scroll: 90 ticks, one every ~16ms, over the grid.
await evaluate(recorder);
for (let i = 0; i < 90; i++) {
  await send("Input.dispatchMouseEvent", { type: "mouseWheel", x: 760, y: 400, deltaX: 0, deltaY: i < 45 ? 120 : -120 });
  await Bun.sleep(16);
}
await Bun.sleep(600);
console.log("scroll:", JSON.stringify(await evaluate(stats)));
console.log("paints during scroll:", await evaluate("window.__paints"));

// Sidebar: collapse and reopen three times.
await evaluate(recorder);
for (let i = 0; i < 6; i++) {
  await evaluate(`document.querySelector(".edge-tab").click()`);
  await Bun.sleep(700);
}
console.log("sidebar:", JSON.stringify(await evaluate(stats)));
ws.close();

