.library-edge-fade {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 120px;
  z-index: 1;
  pointer-events: none;
}
/* The grid clips at the scroller's edges, and blurred cards stay bright, so a
   scrim is what dissolves content into the canvas at those clip lines. It sits
   above the blur: a background under it would be blurred along with the cards.
   The bottom band reaches the window edge, past the 30px main-content padding
   that holds the scroller's bottom clip. */
.library-edge-fade::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(to top, var(--library-canvas) 30px, transparent);
}

.library-scroll {
  position: absolute;
  top: var(--library-top);
  right: var(--main-pad-x);
  bottom: var(--main-pad-bottom);
  left: var(--main-pad-x);
  overflow: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
/* Paper 1.3: the 44px filter row and the grid's 4px top padding put the first
   card 100px below the toolbar's top. */
.library-scroll.has-pinned-query {
  top: calc(var(--library-top) + 100px);
}
/* At rest the first row sits just below the toolbar; scrolled cards still pass
   under the glass. The pinned band already clears the toolbar. */
.library-scroll:not(.has-pinned-query) .library-grid {
  padding-top: 52px;
}

input.new_string:
/* The scroller reaches past the toolbar and bottom padding, nearly to the
   frame's edges, where LibraryEdgeFade blurs the cards out. The grid's padding
   puts the rows back where they rest. */
.library-scroll {
  --scroll-reach-top: 12px;
  --scroll-reach-bottom: 20px;
  position: absolute;
  top: calc(var(--library-top) - var(--scroll-reach-top));
  right: var(--main-pad-x);
  bottom: calc(var(--main-pad-bottom) - var(--scroll-reach-bottom));
  left: var(--main-pad-x);
  overflow: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
/* At rest the first row sits just below the toolbar. Paper 1.3: with a query
   pinned, the 44px filter row puts the first card 100px below the toolbar's
   top. */
.library-scroll .library-grid {
  padding-top: calc(var(--scroll-reach-top) + 52px);
  padding-bottom: var(--scroll-reach-bottom);
}
.library-scroll.has-pinned-query .library-grid {
  padding-top: calc(var(--scroll-reach-top) + 100px);
}

