14	/**
15	 * One shared engine for the live app slots (sidebar mark, search field, roaming
16	 * overlay), so the mascot can move between slots without resetting its clock —
17	 * and so the 60fps frame state never re-renders App, only the subscribed
18	 * figures.
19	 *
20	 * The loop pauses when the tab is hidden or when motion is reduced (params
21	 * still apply as a single sampled frame). Without requestAnimationFrame
22	 * (tests) every push samples immediately.
23	 */
24	const engine = new BotEngine(
25	  RAYON,
26	  "inkling-drift",
27	  SHAPE_BY_ID.get("inkling-splash")?.radii ?? null,
28	  EXPRESSION_BY_ID.get(DEFAULT_EXPRESSION) ?? null,
29	);
30	
31	let clock = 0;
32	let frame: BotFrame = engine.sample(0);
33	let raf = 0;
34	let running = false;
35	const subs = new Set<() => void>();
36	const clockSubs = new Set<(clock: number) => void>();
37	
38	/**
39	 * Two sources of state and expression, one writer. The app pushes the face the
40	 * mascot wears at home; a roaming outing pushes the face it wears out there and
41	 * takes over until it hands back. Keeping both here is what stops the two from
42	 * overwriting each other mid-outing.
43	 */
44	let homeParams: MascotParams = { state: "inkling-drift", expression: DEFAULT_EXPRESSION };
45	let roamParams: MascotParams | null = null;
46	let appliedParams: MascotParams = homeParams;
47	
48	export function prefersReducedMotion(): boolean {
49	  return (
50	    typeof window !== "undefined" &&
51	    typeof window.matchMedia === "function" &&
52	    window.matchMedia("(prefers-reduced-motion: reduce)").matches
53	  );
54	}
55	
56	function emit() {
57	  for (const fn of subs) fn();
58	}
59	
60	function tick(ms: number) {
61	  raf = requestAnimationFrame(tick);
62	  const dt = lastMs ? Math.min((ms - lastMs) / 1000, 0.064) : 0;
63	  lastMs = ms;
64	  clock += dt;
65	  frame = engine.sample(clock);
66	  emit();
67	  for (const fn of clockSubs) fn(clock);
68	}
69	
70	let lastMs = 0;
71	
72	function ensureLoop() {
73	  if (running || typeof requestAnimationFrame !== "function") return;
74	  if (prefersReducedMotion()) return;
75	  if (typeof document !== "undefined" && document.hidden) return;
76	  running = true;
77	  lastMs = 0;
78	  raf = requestAnimationFrame(tick);
79	}
80	
81	function haltLoop() {
82	  if (!running) return;
83	  running = false;
84	  cancelAnimationFrame(raf);
85	}
86	
87	if (typeof document !== "undefined") {
88	  document.addEventListener("visibilitychange", () => {
89	    if (document.hidden) haltLoop();
90	    else if (subs.size > 0 || clockSubs.size > 0) ensureLoop();
91	  });
92	}
93	
94	// The OS reduced-motion setting can flip while the app is open. Without this
95	// the loop would keep running after opting into reduced motion, and never
96	// restart after opting out (subscribers stay mounted, so ensureLoop would not
97	// run again on its own). App.tsx already swaps the drift/sway state on the
98	// same change; this restarts or freezes the clock to match.
99	if (typeof window !== "undefined" && typeof window.matchMedia === "function") {
100	  window.matchMedia("(prefers-reduced-motion: reduce)").addEventListener("change", (event) => {
101	    if (event.matches) {
102	      haltLoop();
103	      frame = engine.sample(clock);
104	      emit();
105	    } else if (subs.size > 0 || clockSubs.size > 0) {
106	      ensureLoop();
107	    }
108	  });
109	}
110	
111	export function subscribeMascot(fn: () => void): () => void {
112	  subs.add(fn);
113	  ensureLoop();
114	  return () => {
115	    subs.delete(fn);
116	    if (subs.size === 0 && clockSubs.size === 0) haltLoop();
117	  };
118	}
119	
120	/**
121	 * The engine's own clock, in seconds since load, on every frame. The roaming
122	 * controller rides it instead of opening a timer of its own: the loop already
123	 * stops for a hidden tab and for reduced motion, which are exactly the moments
124	 * the mascot must not decide anything.
125	 */
126	export function onMascotClock(fn: (clock: number) => void): () => void {
127	  clockSubs.add(fn);
128	  ensureLoop();
129	  return () => {
130	    clockSubs.delete(fn);
131	    if (subs.size === 0 && clockSubs.size === 0) haltLoop();
132	  };
133	}
134	
135	export function getMascotFrame(): BotFrame {
136	  return frame;
137	}
138	
139	/**
140	 * The only path to the engine's state and face. Roaming overrides the app's.
141	 *
142	 * Both sources push on every change of their own inputs, which during an outing
143	 * is every stop, and the engine already ignores a state it is already in. The
144	 * guard here is so the hand-back is legible: when roaming hands the engine over
145	 * and the app's own face happens to equal the face the outing was wearing,
146	 * there is one path that resolves the conflict rather than two.
147	 */
148	function apply() {
149	  const active = roamParams ?? homeParams;
150	  if (active.state === appliedParams.state && active.expression === appliedParams.expression)
151	    return;
152	  appliedParams = active;
153	  engine.setState(active.state, clock);
154	  engine.setExpression(
155	    EXPRESSION_BY_ID.get(active.expression) ?? EXPRESSION_BY_ID.get(DEFAULT_EXPRESSION) ?? null,
156	    clock,
157	  );
158	  if (!running) {
159	    frame = engine.sample(clock);
160	    emit();
161	  }
162	}
163	
164	export function pushMascotParams({ state, expression }: MascotParams) {
165	  homeParams = { state, expression };
166	  apply();
167	}
168	
169	/** An outing pushes its own face here, and pushes null to hand the engine back. */
170	export function pushRoamParams(params: MascotParams | null) {
171	  roamParams = params;
172	  // A gaze outlives the outing that asked for it unless it is cleared with the
173	  // hand-off, and a mascot back in its slot should look where its state looks.
174	  if (!roamParams) engine.setLook(null, clock);
175	  apply();
176	}
177	
178	/** Gaze target, absolute in degrees. null returns the gaze to the current state. */
179	export function pushMascotLook(look: Look | null) {
180	  engine.setLook(look, clock);
181	  if (!running) {
182	    frame = engine.sample(clock);
183	    emit();
184	  }
185	}
