187	/** Pure re-read for tests and frozen previews: no clock advance, no emit. */
188	export function sampleMascotAt(t: number): BotFrame {
189	  return engine.sample(t);
190	}
191	
192	function useMascotFrame(): BotFrame {
193	  return useSyncExternalStore(subscribeMascot, getMascotFrame);
194	}
