    border-right: 0;
    border-radius: var(--frame-radius) 0 0 var(--frame-radius);
    background: var(--library-frame);
  }
  .sidebar-close,
  .sidebar-toggle {
    display: none;
  }
  /* Centred on the brand lockup's 48px midline. */
  .edge-tab {
