} from '@hugeicons/core-free-icons';
import { motion, AnimatePresence } from 'motion/react';

export interface DisclosureItem {
  icon: ReactNode;
  label: string;
}

export interface CreateNewDisclosureProps {
  items?: DisclosureItem[];
  initialOpen?: boolean;
  autoPlay?: boolean;
  forceLightMode?: boolean;
}

interface GridItemProps {
  icon: ReactNode;
  label: string;
  forceLightMode?: boolean;
}

const GridItem: FC<GridItemProps> = ({ icon, label, forceLightMode }) => {
  return (
    <motion.button className={`group flex flex-col items-center justify-center gap-1 sm:gap-1.5 rounded-[20px] sm:rounded-[24px] px-1 py-3 sm:py-4 transition-all duration-200 hover:bg-[#F4F2EA] ${!forceLightMode ? 'dark:hover:bg-neutral-800/50' : ''}`}>
      <div className={`text-[#8B8B8B] transition-colors group-hover:text-[#4A4A4A] [&>svg]:size-5 sm:[&>svg]:size-7 ${!forceLightMode ? 'dark:text-neutral-500 dark:group-hover:text-neutral-300' : ''}`}>
        {icon}
      </div>
      <span className={`text-[12px] sm:text-[14px] font-medium tracking-tight text-[#4A4A4A] ${!forceLightMode ? 'dark:text-neutral-400' : ''}`}>
        {label}
      </span>
    </motion.button>
  );
};

export const CreateNewDisclosure: FC<CreateNewDisclosureProps> = ({
  items,
  initialOpen = false,
  autoPlay,
  forceLightMode,
}) => {
  const [open, setOpen] = useState<boolean>(initialOpen);

  useEffect(() => {
    if (autoPlay === true) {
      setOpen(true);
    } else if (autoPlay === false) {
      setOpen(false);
    }
  }, [autoPlay]);

  const defaultItems: DisclosureItem[] = [
    { icon: <HugeiconsIcon icon={Folder01Icon} strokeWidth={1.5} />, label: 'Project' },
    { icon: <HugeiconsIcon icon={TaskEdit01Icon} strokeWidth={1.5} />, label: 'Task' },
