    { icon: <HugeiconsIcon icon={Award01Icon} strokeWidth={1.5} />, label: 'Goal' },
    { icon: <HugeiconsIcon icon={Flag02Icon} strokeWidth={1.5} />, label: 'Milestone' },
    { icon: <HugeiconsIcon icon={Calendar04Icon} strokeWidth={1.5} />, label: 'Reminder' },
