          exit={{ opacity: 0, transition: { duration: 0.1 } }}
          style={{ borderRadius: 32 }}
          transition={{ type: 'spring', bounce: 0.1, duration: 0.4 }}
          className={`flex cursor-pointer items-center gap-2 bg-[#F4F4F9] px-6 py-3.5 sm:px-8 sm:py-4 text-base sm:text-lg font-medium whitespace-nowrap text-[#26262B] transition-colors ${!forceLightMode ? 'dark:bg-zinc-800 dark:text-zinc-100' : ''}`}
        >
          <div className="flex items-center gap-2">
            <HugeiconsIcon
              icon={Add01Icon}
              size={24}
              className={`text-[#26262B] sm:size-[26px] ${!forceLightMode ? 'dark:text-zinc-100' : ''}`}
              strokeWidth={1.5}
            />
            <motion.span layoutId="cnd-label">Create New</motion.span>
          </div>
        </motion.button>
      ) : (
        <motion.div
          key="expanded"
          layoutId="cnd-container"
