        >
          <div className="flex items-center justify-between px-4 py-3.5">
            <motion.span
              layoutId="cnd-label"
              className={`text-[15px] sm:text-[16px] font-semibold text-[#5C5A56] ${!forceLightMode ? 'dark:text-zinc-100' : ''}`}
            >
              Create New
            </motion.span>
            <motion.button
              onClick={() => setOpen(false)}
              whileTap={{ scale: 0.95 }}
              className={`flex h-6 w-6 cursor-pointer items-center justify-center rounded-full bg-[#B8B5B0] ${!forceLightMode ? 'dark:bg-neutral-700' : ''}`}
            >
              <HugeiconsIcon icon={Cancel01Icon} size={16} color="#ffffff" strokeWidth={2.5} />
            </motion.button>
          </div>

          <div className={`grid grid-cols-3 gap-1 rounded-t-[20px] rounded-b-[20px] bg-white p-3 sm:p-4 border border-black/[0.06] dark:border-white/[0.08] shadow-xs ${!forceLightMode ? 'dark:bg-neutral-950' : ''}`}>
            {disclosureItems.map((item, index) => (
              <GridItem key={index} icon={item.icon} label={item.label} forceLightMode={forceLightMode} />
            ))}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export default function CreateNewDisclosureDemo({ autoPlay, forceLightMode }: { autoPlay?: boolean, forceLightMode?: boolean }) {
    const customItems = [
        { icon: <HugeiconsIcon icon={Folder01Icon} size={28} strokeWidth={1.5} />, label: "Project" },
        { icon: <HugeiconsIcon icon={TaskEdit01Icon} size={28} strokeWidth={1.5} />, label: "Task" },
        { icon: <HugeiconsIcon icon={NoteIcon} size={28} strokeWidth={1.5} />, label: "Note" },
        { icon: <HugeiconsIcon icon={Award01Icon} size={28} strokeWidth={1.5} />, label: "Goal" },
        { icon: <HugeiconsIcon icon={Flag02Icon} size={28} strokeWidth={1.5} />, label: "Milestone" },
        { icon: <HugeiconsIcon icon={Calendar04Icon} size={28} strokeWidth={1.5} />, label: "Reminder" },
    ];

    return (
        <div className="flex items-center justify-center w-full px-4">
            <CreateNewDisclosure items={customItems} initialOpen={false} autoPlay={autoPlay} forceLightMode={forceLightMode} />
        </div>
    );
}

