// usage: bun pr-shots.ts <port> <outDir>
const [port, outDir] = process.argv.slice(2);
const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const ws = new WebSocket(list.find((t: any) => t.type === "page" && t.url.startsWith("app://")).webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r, { once: true }));
let id = 0;
const pending = new Map<number, (v: any) => void>();
ws.addEventListener("message", (e) => {
  const m = JSON.parse(String(e.data));
  if (m.id && pending.has(m.id)) { pending.get(m.id)!(m); pending.delete(m.id); }
});
const send = (method: string, params: object = {}) =>
  new Promise<any>((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expression: string) => {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  return r.result?.exceptionDetails ? `ERR ${r.result.exceptionDetails.exception?.description}` : r.result?.result?.value;
};
const sleep = (ms: number) => Bun.sleep(ms);
const mouse = (type: string, x: number, y: number, button = "left") =>
  send("Input.dispatchMouseEvent", { type, x, y, button, clickCount: 1 });
