  ev(`(()=>{const e=document.querySelector(${JSON.stringify(selector)}); if(!e) return null; const b=e.getBoundingClientRect(); return [b.x+b.width/2,b.y+b.height/2]})()`);
const key = async (k: string, code: number) => { for (const type of ["keyDown", "keyUp"]) await send("Input.dispatchKeyEvent", { type, key: k, code: k, windowsVirtualKeyCode: code }); };
const shot = async (name: string) => {
  const s = await send("Page.captureScreenshot", { format: "png" });
  await Bun.write(`${outDir}/${name}.png`, Buffer.from(s.result.data, "base64"));
};

